from pathlib import Path
import re,json,html
p=Path('faust-reader/dist'); t=(p/'faust.txt').read_text(encoding='utf-8-sig'); lines=t.splitlines(); c=lines.index('Contents'); start=next(i for i in range(c+1,len(lines)) if lines[i]=='Zueignung'); titles=[x.strip() for x in lines[c+1:start] if x.strip()]; end=next(i for i,x in enumerate(lines) if x.startswith('*** END OF THE PROJECT')); positions=[]; cursor=start
for title in titles:
 i=next(i for i in range(cursor,end) if lines[i].strip().rstrip('.')==title.rstrip('.')); positions.append(i); cursor=i+1
chapters=[{'title':title,'text':'\n'.join(lines[positions[i]+1:positions[i+1] if i+1<len(positions) else end]).strip()} for i,title in enumerate(titles)]
assert len(chapters)==28
page='''<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>FAUST · 괴테의 파우스트</title><style>*{box-sizing:border-box}body{margin:0;background:#f6f2e9;color:#292a25;font-family:Georgia,'Times New Roman',serif}header{padding:27px 5vw;border-bottom:1px solid #cfc9bb;display:flex;justify-content:space-between;align-items:center}header b{letter-spacing:.3em}button,select{background:transparent;border:1px solid #b8b3a6;padding:10px;color:inherit;cursor:pointer}main{display:grid;grid-template-columns:280px 1fr;max-width:1300px;margin:auto}aside{padding:35px 25px;border-right:1px solid #cfc9bb}aside a{display:block;color:inherit;text-decoration:none;padding:9px 8px;font:14px/1.4 system-ui}aside a.active{background:#e1e4d5;color:#34472d}article{padding:55px clamp(24px,6vw,100px);min-width:0}.eyebrow{font:12px system-ui;letter-spacing:.16em;color:#667356}h1{font-weight:normal;font-size:clamp(40px,6vw,70px);margin:15px 0}h2{font-weight:normal;font-size:34px;border-top:1px solid #ccc5b6;padding-top:30px}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:var(--size,20px)/1.9 Georgia,serif}nav{display:flex;justify-content:space-between;margin:50px 0}footer{font:13px/1.8 system-ui;color:#777}footer a{color:inherit}@media(max-width:760px){main{display:block}aside{max-height:220px;overflow:auto;border-bottom:1px solid #ccc}article{padding-top:30px}header{gap:15px;flex-wrap:wrap}} </style><header><b>FAUST</b><span>괴테 · 파우스트 제1부</span><div><button id="minus" aria-label="글자 축소">A−</button> <button id="plus" aria-label="글자 확대">A+</button></div></header><main><aside><p class="eyebrow">INHALT / 장면 목차</p><div id="toc"></div></aside><article><p class="eyebrow">JOHANN WOLFGANG VON GOETHE</p><h1>Faust.</h1><p>Der Tragödie erster Teil · 독일어 원문</p><h2 id="title" lang="de"></h2><pre id="text" lang="de"></pre><nav><button id="prev">← 이전 장면</button><span id="count"></span><button id="next">다음 장면 →</button></nav><footer>원문의 행과 장면 구분을 보존했습니다.<br>출처: <a href="https://www.gutenberg.org/ebooks/2229">Project Gutenberg · eBook #2229</a> · <a href="faust.txt">전체 원문 및 라이선스</a></footer></article></main><script>const chapters=DATA;let current=0,size=20;const toc=document.getElementById('toc');chapters.forEach((c,i)=>{let a=document.createElement('a');a.href='#scene-'+(i+1);a.textContent=String(i+1).padStart(2,'0')+'  '+c.title;toc.append(a)});function render(){current=Math.max(0,Math.min(chapters.length-1,(parseInt(location.hash.replace('#scene-',''))||1)-1));document.getElementById('title').textContent=chapters[current].title;document.getElementById('text').textContent=chapters[current].text;document.getElementById('count').textContent=(current+1)+' / '+chapters.length;document.querySelectorAll('#toc a').forEach((a,i)=>a.classList.toggle('active',i===current));document.getElementById('prev').disabled=current===0;document.getElementById('next').disabled=current===chapters.length-1}onhashchange=()=>{render();document.querySelector('article').scrollIntoView({behavior:'smooth'})};document.getElementById('prev').onclick=()=>location.hash='scene-'+current;document.getElementById('next').onclick=()=>location.hash='scene-'+(current+2);function resize(n){size=Math.max(14,Math.min(32,size+n));document.documentElement.style.setProperty('--size',size+'px')}document.getElementById('minus').onclick=()=>resize(-2);document.getElementById('plus').onclick=()=>resize(2);render();</script></html>'''.replace('DATA',json.dumps(chapters,ensure_ascii=False).replace('</','<\\/'))
(p/'index.html').write_text(page,encoding='utf-8');print('Verified:',len(chapters),'scenes;',sum(len(c['text']) for c in chapters),'characters')



